// --- 2. タブ切り替えロジック ＆ ヘッダーナビゲーション ---
function switchTab(tabId, scrollToTop = false) {
  const panes = document.querySelectorAll('.tab-pane');
  panes.forEach(p => p.classList.remove('active'));

  const navBtns = document.querySelectorAll('.tab-nav .tab-btn, .main-nav-btn');
  navBtns.forEach(b => {
    b.classList.remove('active');
    const oc = (b.getAttribute && b.getAttribute('onclick')) || '';
    const dt = (b.getAttribute && b.getAttribute('data-tab')) || '';
    if (oc.includes(tabId) || dt === tabId) {
      b.classList.add('active');
    }
  });

  const targetPane = document.getElementById(tabId);
  if (targetPane) {
    targetPane.classList.add('active');
  }

  if (tabId === 'tab-favorites' && typeof renderFavoritesHub === 'function') {
    renderFavoritesHub();
  }

  if (scrollToTop) {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
}

function triggerQuickPrint() {
  window.print();
}

// ==========================================================================
// スムーズスクロール＆パルスハイライト共通関数（固定ヘッダー自動オフセット対応）
// ==========================================================================
function smoothScrollToElement(elem, customOffset) {
  if (!elem) return;
  const navbar = document.querySelector('.navbar');
  const navHeight = navbar ? navbar.offsetHeight : 110;
  const offset = (typeof customOffset === 'number') ? customOffset : (navHeight + 20);

  setTimeout(() => {
    const rect = elem.getBoundingClientRect();
    const scrollTop = window.pageYOffset || (document.documentElement ? document.documentElement.scrollTop : 0) || 0;
    const targetY = rect.top + scrollTop - offset;

    window.scrollTo({
      top: Math.max(0, targetY),
      behavior: 'smooth'
    });

    elem.classList.remove('target-pulse');
    void elem.offsetWidth; // リフロー強制
    elem.classList.add('target-pulse');
  }, 100);
}

function clearSearch() {
  const heroInput = document.getElementById('drug-search-input');
  if (heroInput) heroInput.value = '';
  const sDrop = document.getElementById('suggest-dropdown');
  if (sDrop) sDrop.style.display = 'none';
  const sBox = document.getElementById('suggestBox');
  if (sBox) sBox.style.display = 'none';
}

function handleHeroSearchKeydown(e, input) {
  if (e.key === 'Escape') {
    const d = document.getElementById('suggest-dropdown');
    if (d) d.style.display = 'none';
  } else if (e.key === 'Enter') {
    e.preventDefault();
    quickSearch(input.value.trim());
  }
}

function quickSearch(keyword) {
  executeUniversalSearch(keyword);
}



