  "タケキャブ": { crush: "ng", susp: "ok", pack: "caution", crushText: "❌ 不可", suspText: "⭕ 10分崩壊", packText: "⚠️ 直前", reason: "粉砕で激しい苦味あり。吸湿性があるため一包化は直前開封推奨。簡易懸濁は温湯で10分崩壊・通過良好。", alt: "タケキャブOD錠、ネキシウム懸濁用" },
  "ボノプラザン": { crush: "ng", susp: "ok", pack: "caution", crushText: "❌ 不可", suspText: "⭕ 10分崩壊", packText: "⚠️ 直前", reason: "粉砕で激しい苦味あり。吸湿性があるため一包化は直前開封推奨。簡易懸濁は温湯で10分崩壊・通過良好。", alt: "タケキャブOD錠、ネキシウム懸濁用" },
  "ネキシウム": { crush: "ng", susp: "ok", pack: "ng", crushText: "❌ 不可", suspText: "⭕ 懸濁可", packText: "❌ 不可", reason: "腸溶顆粒含有カプセル。粉砕すると胃酸で失活。温湯で顆粒のまま崩壊懸濁し通過可能。一包化NG。", alt: "ネキシウム懸濁用顆粒分包" },
  "エソメプラゾール": { crush: "ng", susp: "ok", pack: "ng", crushText: "❌ 不可", suspText: "⭕ 懸濁可", packText: "❌ 不可", reason: "腸溶顆粒含有カプセル。粉砕すると胃酸で失活。温湯で顆粒のまま崩壊懸濁し通過可能。一包化NG。", alt: "ネキシウム懸濁用顆粒分包" },
  "パリエット": { crush: "ng", susp: "ng", pack: "caution", crushText: "❌ 不可", suspText: "❌ 不可", packText: "⚠️ 防湿", reason: "腸溶錠。粉砕すると胃酸で速やかに失活。簡易懸濁も不可。一包化は防湿管理下で注意。", alt: "タケキャブOD錠、ネキシウム懸濁用" },
  "ラベプラゾール": { crush: "ng", susp: "ng", pack: "caution", crushText: "❌ 不可", suspText: "❌ 不可", packText: "⚠️ 防湿", reason: "腸溶錠。粉砕すると胃酸で速やかに失活。簡易懸濁も不可。一包化は防湿管理下で注意。", alt: "タケキャブOD錠、ネキシウム懸濁用" },
  "タケプロン": { crush: "ng", susp: "ok", pack: "ok", crushText: "❌ 不可", suspText: "⭕ 崩壊通過", packText: "⭕ 可", reason: "OD錠は水で速やかに崩壊し微小腸溶顆粒が通過。微粒子をすりつぶす粉砕は不可。", alt: "タケプロンOD錠" },
  "ランソプラゾール": { crush: "ng", susp: "ok", pack: "ok", crushText: "❌ 不可", suspText: "⭕ 崩壊通過", packText: "⭕ 可", reason: "OD錠は水で速やかに崩壊し微小腸溶顆粒が通過。微粒子をすりつぶす粉砕は不可。", alt: "タケプロンOD錠" },
  "マグミット": { crush: "ok", susp: "ok", pack: "caution", crushText: "⭕ 可", suspText: "⭕ 5分崩壊", packText: "⚠️ 硬化", reason: "粉砕・懸濁可能。空気中CO2・湿気で炭酸マグネシウムに変化し難溶化するため長期一包化注意。", alt: "細粒" },
