  "リンゼス": { crush: "ng", susp: "ng", pack: "ng", crushText: "❌ 不可", suspText: "❌ 不可", packText: "❌ 吸湿激", reason: "ペプチド製剤。吸湿性激甚で失活するため脱カプセル厳禁。乾燥剤入りPTP直前開封必須。", alt: "モビコール、アミティーザ" },
  "グーフィス": { crush: "ok", susp: "ok", pack: "ok", crushText: "⭕ 可", suspText: "⭕ 5分崩壊", packText: "⭕ 可", reason: "普通錠粉砕可能。懸濁性良好。", alt: "普通錠粉砕" },
