function executeUniversalSearch(query) {
  const dropdown = document.getElementById('suggest-dropdown');
  if (dropdown) dropdown.style.display = 'none';
  const heroInput = document.getElementById('drug-search-input');
  if (heroInput && query) heroInput.value = query;

  if (!query) return;
  const rawQuery = query.trim();
  if (!rawQuery) return;

  // 表記ゆれを正規化
  const normalized = normalizeSearchQuery(rawQuery);

  // 1. 特殊機能・神ツールへのスマート単独表示
  if (normalized === '併用禁忌') {
    filterSpecialToTopic('sec-contra', '一発アウト併用禁忌 ＆ CYP代謝');
    return;
  }
  if (normalized === '粉砕') {
    filterSpecialToTopic('sec-crush', '粉砕・簡易懸濁可否マスター');
    return;
  }
  if (normalized === '小児') {
    filterSpecialToTopic('sec-peds', '小児体重換算計算機 ＆ 飲ませ方');
    return;
  }
  if (normalized === '疑義照会') {
    filterSpecialToTopic('sec-inquiry', '疑義照会の神フレーズ ＆ 医師交渉術');
    return;
  }
  if (normalized === '第一選択') {
    jumpToFirstLine();
    return;
  }
  if (normalized === '生活指導') {
    filterSpecialToTopic('sec-lifestyle', '疾患別 実戦生活指導集');
    return;
  }

  // 2. 同効薬比較（tab-comparison）の特定テーブル単独表示
  if (normalized === 'めまい') {
    filterCompToKeyword('めまい');
    return;
  }
  if (normalized === '禁煙') {
    filterCompToKeyword('禁煙');
    return;
  }
  if (normalized === '禁酒') {
    filterCompToKeyword('アルコール依存症治療薬');
    return;
  }
  if (normalized === 'インスリン') {
    filterCompToKeyword('インスリン');
    return;
  }
  if (normalized === 'doac') {
    filterCompToKeyword('doac');
    return;
  }
  if (normalized === 'スタチン') {
    filterCompToKeyword('スタチン');
    return;
  }
  if (normalized === '便秘') {
    filterCompToKeyword('便秘');
    return;
  }
  if (normalized === '吸入') {
    filterCompToKeyword('吸入');
    return;
  }
  if (normalized === '頭痛') {
    filterCompToKeyword('片頭痛');
    return;
  }
  if (normalized === '痛風') {
    filterCompToKeyword('痛風');
    return;
  }
  if (normalized === '骨粗鬆症') {
    filterCompToKeyword('骨粗鬆症');
    return;
  }
  if (normalized === '睡眠薬') {
    filterCompToKeyword('睡眠薬');
    return;
  }
  if (normalized === '抗うつ') {
    filterCompToKeyword('抗うつ薬');
    return;
  }
  if (normalized === '逆流性食道炎') {
    filterCompToKeyword('酸関連');
    return;
  }

  // 3. 疾患ガイド固有カード単独表示
  if (normalized === 'オグサワ') {
    filterGuideToCard('c24', 'オグサワ処方（呼吸器・感染症）');
    return;
  }
  if (normalized === '心不全') {
    filterGuideToCard('c1', '心不全 ＆ ファンタスティック・フォー');
    return;
  }
  if (normalized === '糖尿病') {
    filterGuideToCard('c2', '糖尿病 ＆ 薬物使い分け');
    return;
  }
  if (normalized === '高血圧') {
    filterGuideToCard('c3', '高血圧 ＆ 降圧薬選択');
    return;
  }

  // 4. 同効薬比較テーブル内でキーワードを走査してマッチすれば単独表示
  const compMatches = filterCompToKeyword(rawQuery);
  if (compMatches && compMatches > 0) {
    return;
  }

  // 5. 新薬トレンド図鑑を走査してマッチすれば単独表示
  const newDrugRows = document.querySelectorAll('#tab-newdrugs tr.trend-row');
  let hasNewDrugMatch = false;
  newDrugRows.forEach(row => {
    if (row.innerText.toLowerCase().includes(rawQuery.toLowerCase())) {
      hasNewDrugMatch = true;
    }
  });
  if (hasNewDrugMatch) {
    filterNewDrugsToKeyword(rawQuery);
    return;
  }

  // 6. 疾患ガイドの全カード内を走査してマッチすればそのカードだけ単独表示
  const guideCards = document.querySelectorAll('#guide-cards-container .card');
  for (const card of guideCards) {
    if (card.innerText.toLowerCase().includes(rawQuery.toLowerCase())) {
      filterGuideToCard(card.id, rawQuery);
      return;
    }
  }

  // 7. DRUG_DB の検索
  const hits = DRUG_DB.filter(d => 
    d.name.toLowerCase().includes(rawQuery.toLowerCase()) || 
    d.gen.toLowerCase().includes(rawQuery.toLowerCase()) || 
    d.char.toLowerCase().includes(rawQuery.toLowerCase()) ||
    d.desc.toLowerCase().includes(rawQuery.toLowerCase()) ||
    d.cat.toLowerCase().includes(rawQuery.toLowerCase())
  );
  if (hits.length > 0) {
    const targetDrug = hits[0];
    jumpToDrugDirectly(targetDrug);
    return;
  }

  // 8. 該当なし時は臨床事典タブ（tab-dict）で単独絞り込み
  switchTab('tab-dict');
  const dictInput = document.getElementById('dictSearchInput');
  if (dictInput) {
    dictInput.value = rawQuery;
    if (typeof filterDictSearch === 'function') filterDictSearch(rawQuery);
  }
}

