function toggleFrameworkDetails(btn) {
  const details = document.getElementById('framework-details');
  if (!details) return;
  if (details.style.display === 'none') {
    details.style.display = 'block';
    btn.innerText = '▲ 閉じる';
  } else {
    details.style.display = 'none';
    btn.innerText = '▼ 開く';
  }
}

