// --- 7. ホーム＆全薬剤検索ダッシュボード用スクリプト ---
function handleSearchInput(input) {
  const val = input.value.trim().toLowerCase();
  const suggestBox = document.getElementById('suggestBox');
  if (!suggestBox) return;
  suggestBox.innerHTML = '';

  if (!val) {
    suggestBox.style.display = 'none';
    return;
  }

  const hits = DRUG_DB.filter(d => 
    d.name.toLowerCase().includes(val) || 
    d.gen.toLowerCase().includes(val) || 
    d.char.toLowerCase().includes(val) ||
    d.desc.toLowerCase().includes(val)
  );

  if (hits.length === 0) {
    suggestBox.innerHTML = '<div style="padding:10px 14px;color:#94a3b8;font-size:0.88rem;">該当する薬剤が見つかりません</div>';
    suggestBox.style.display = 'block';
    return;
  }

  hits.slice(0, 8).forEach(drug => {
    const item = document.createElement('div');
    item.className = 'suggest-item';
    item.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <strong style="color:var(--primary); font-size:0.92rem;">${drug.name}</strong>
        <span style="font-size:0.75rem; color:#64748b; background:#f1f5f9; padding:2px 8px; border-radius:4px;">${drug.cat}</span>
      </div>
      <div style="font-size:0.8rem; color:#475569; margin-top:3px;">${drug.char}</div>
    `;
    item.onclick = () => {
      jumpToDrugDirectly(drug);
    };
    suggestBox.appendChild(item);
  });
  suggestBox.style.display = 'block';
}

function handleSearchKeydown(e) {
  if (e.key === 'Escape') {
    const suggestBox = document.getElementById('suggestBox');
    if (suggestBox) suggestBox.style.display = 'none';
  }
}

function fillSearch(keyword) {
  const input = document.getElementById('mainSearchInput');
  if (!input) return;
  input.value = keyword;
  handleSearchInput(input);
}

// --- 8. 新薬トレンド図鑑 スクリプト（発売日・改訂日タイムライン対応） ---
let currentTrendFilter = 'all';

function filterTrend(cls, btn) {
  currentTrendFilter = cls;
  const btns = document.querySelectorAll('#tab-newdrugs .f-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const secs = document.querySelectorAll('#tab-newdrugs .trend-section');
  const rows = document.querySelectorAll('#tab-newdrugs tr.trend-row');

  if (cls === 'all') {
    secs.forEach(s => s.style.display = 'block');
    rows.forEach(r => r.style.display = '');
  } else if (cls.startsWith('yr-')) {
    secs.forEach(s => {
      s.style.display = s.classList.contains(cls) ? 'block' : 'none';
    });
    rows.forEach(r => r.style.display = '');
  } else if (cls.startsWith('t-')) {
    secs.forEach(s => {
      const matchingRows = s.querySelectorAll(`tr.trend-row.${cls}`);
      if (matchingRows.length > 0) {
        s.style.display = 'block';
        s.querySelectorAll('tr.trend-row').forEach(r => {
          r.style.display = r.classList.contains(cls) ? '' : 'none';
        });
      } else {
        s.style.display = 'none';
      }
    });
  }
}

function filterNewDrugsSearch() {
  const input = document.getElementById('newDrugSearchInput');
  const terms = input ? input.value.trim().toLowerCase().split(/\s+/).filter(Boolean) : [];
  const secs = document.querySelectorAll('#tab-newdrugs .trend-section');

  if (terms.length === 0) {
    const activeBtn = document.querySelector(`#tab-newdrugs .f-btn[onclick*="${currentTrendFilter}"]`);
    filterTrend(currentTrendFilter, activeBtn);
    return;
  }

  secs.forEach(sec => {
    let secHasMatch = false;
    sec.querySelectorAll('tr.trend-row').forEach(row => {
      const text = row.innerText.toLowerCase();
      const match = terms.every(t => text.includes(t));
      if (match) {
        row.style.display = '';
        secHasMatch = true;
      } else {
        row.style.display = 'none';
      }
    });
    sec.style.display = secHasMatch ? 'block' : 'none';
  });
}

