function showOtc(cls, btn) {
  const btns = document.querySelectorAll('#tab-otc .tab-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const secs = document.querySelectorAll('#tab-otc .otc-section');
  secs.forEach(s => {
    if (cls === 'all' || s.classList.contains(cls)) {
      s.style.display = 'block';
    } else {
      s.style.display = 'none';
    }
  });
}

// --- 11. 服薬フォロー＆TR スクリプト ---
function showFu(cls, btn) {
  const btns = document.querySelectorAll('#tab-followup .tab-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const secs = document.querySelectorAll('#tab-followup .fu-section');
  secs.forEach(s => {
    if (cls === 'all' || s.classList.contains(cls)) {
      s.style.display = 'block';
    } else {
      s.style.display = 'none';
    }
  });
}

function filterDiseaseCheck(cat, btn) {
  const btns = document.querySelectorAll('.disease-filter-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
  cards.forEach(card => {
    const cCat = card.getAttribute('data-cat') || '';
    if (cat === 'all' || cCat.split(' ').includes(cat)) {
      card.style.display = 'block';
    } else {
      card.style.display = 'none';
    }
  });
}

