function handleDiseaseCheckSearch(query) {
  const q = (query || '').trim().toLowerCase();
  const clearBtn = document.getElementById('diseaseCheckClearBtn');
  if (clearBtn) {
    clearBtn.style.display = q ? 'flex' : 'none';
  }

  const suggestArea = document.getElementById('diseaseCheckSuggestArea');
  const suggestPills = document.getElementById('diseaseCheckSuggestPills');

  if (!q) {
    if (suggestArea) suggestArea.style.display = 'none';
    if (suggestPills) suggestPills.innerHTML = '';
    const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
    cards.forEach(card => card.style.display = 'block');
    return;
  }

  // 1. 超精密・処方鑑別データベースの検索
  const matchedDiffs = [];
  DRUG_DIFF_MAP.forEach(item => {
    const isMatched = item.drugs.some(d => d.toLowerCase().includes(q) || q.includes(d.toLowerCase()));
    if (isMatched) {
      item.diffs.forEach(diff => {
        if (!matchedDiffs.some(m => m.cardNum === diff.cardNum && m.subType === diff.subType)) {
          matchedDiffs.push(diff);
        }
      });
    }
  });

  // サジェストピル・病態特定カードの描画
  if (matchedDiffs.length > 0 && suggestArea && suggestPills) {
    suggestArea.style.display = 'block';
    suggestPills.innerHTML = matchedDiffs.map(d => `
      <div class="diff-subtype-card" onclick="jumpToDiseaseCard(${d.cardNum}, '${q}')" style="width:100%; box-sizing:border-box;">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px; margin-bottom:2px;">
          <span class="diff-badge-subtype">${d.subType}</span>
          <strong style="font-size:0.88rem; color:#065f46;">📌 ${d.name} ➔ チェックへ</strong>
        </div>
        <div class="diff-criteria-text">${d.criteria}</div>
        <div style="font-size:0.77rem; color:#334155; line-height:1.45; margin-top:2px;">
          <strong>💡 臨床根拠：</strong>${d.reason}
        </div>
        <div class="diff-keypoint-text">
          <strong>⚠️ 確認急所：</strong>${d.keyPoint}
        </div>
      </div>
    `).join('');
  } else if (suggestArea) {
    suggestArea.style.display = 'none';
  }

  // 2. 全46疾患カードのリアルタイム絞り込み
  const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
  cards.forEach(card => {
    const text = card.textContent.toLowerCase();
    const isDirectMatched = matchedDiffs.some(d => {
      const titleEl = card.querySelector('strong');
      return titleEl && titleEl.textContent.trim().startsWith(d.cardNum + '.');
    });
    if (text.includes(q) || isDirectMatched) {
      card.style.display = 'block';
    } else {
      card.style.display = 'none';
    }
  });
}

function clearDiseaseCheckSearch() {
  const input = document.getElementById('diseaseCheckSearchInput');
  if (input) input.value = '';
  handleDiseaseCheckSearch('');
}

function quickDiseaseSearch(keyword) {
  const input = document.getElementById('diseaseCheckSearchInput');
  if (input) {
    input.value = keyword;
    handleDiseaseCheckSearch(keyword);
    input.focus();
  }
}

function jumpToDiseaseCard(cardNum, drugKeyword) {
  const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
  let targetCard = null;
  cards.forEach(card => {
    const titleEl = card.querySelector('strong');
    if (titleEl && titleEl.textContent.trim().startsWith(cardNum + '.')) {
      targetCard = card;
      card.style.display = 'block';
    }
  });

  if (targetCard) {
    targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
    targetCard.classList.remove('diff-card-highlight');
    void targetCard.offsetWidth; // reflow
    targetCard.classList.add('diff-card-highlight');
    setTimeout(() => {
      targetCard.classList.remove('diff-card-highlight');
    }, 2500);
  }
}


// --- サジェストからの直接ジャンプ＆ハイライト関数 ---
function jumpToDrugDirectly(drug) {
  const dropdown = document.getElementById('suggest-dropdown');
  if (dropdown) dropdown.style.display = 'none';
  const sBox = document.getElementById('suggestBox');
  if (sBox) sBox.style.display = 'none';

  if (!drug) return;

  const targetTab = (drug.gId && drug.gId.startsWith('tab-')) ? drug.gId : 'tab-guide';
  switchTab(targetTab);

  if (targetTab === 'tab-guide') {
    const cardId = drug.gId || 'all';
    filterGuideCard(cardId, null);
    const sideLink = document.querySelector(`.guide-nav-link[onclick*="'${cardId}'"]`);
    if (sideLink) {
      document.querySelectorAll('.guide-nav-link').forEach(l => l.classList.remove('active'));
      sideLink.classList.add('active');
    }
    setTimeout(() => {
      let targetElem = null;
      if (drug.subId) targetElem = document.getElementById(drug.subId);
      if (!targetElem && cardId !== 'all') targetElem = document.getElementById(cardId);
      if (targetElem) {
        // カード内の該当薬剤テキストを探してピンポイントスクロール
        const drugNameSimple = drug.name.split('/')[0].split(' ')[0].replace(/[（(].*$/, '').trim();
        const walker = document.createTreeWalker(targetElem, NodeFilter.SHOW_ELEMENT);
        let node;
        let foundRow = null;
        while ((node = walker.nextNode())) {
          if (node.children.length === 0 && node.innerText && node.innerText.includes(drugNameSimple)) {
            foundRow = node.closest('tr') || node.closest('.pearl-box') || node.closest('.point-box') || node;
            break;
          }
        }
        smoothScrollToElement(foundRow || targetElem);
      }
    }, 120);
  } else if (targetTab === 'tab-newdrugs') {
    filterTrend(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-newdrugs .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-newdrugs');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-special') {
    showTopic(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-special .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-special');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-otc') {
    showOtc(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-otc .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-otc');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-followup') {
    showFu(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-followup .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-followup');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-comparison') {
    filterCompSec(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-comparison .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-comparison');
      smoothScrollToElement(sec);
    }, 120);
  }
}

