// --- 14. 初期化処理 ---
document.addEventListener('DOMContentLoaded', () => {
  initDictCompoundingBadges();
  renderWeeklyTopics();
  initFavoritesButtons();
  updateFavoriteCountBadges();
  initAllDrugsList();
  
  // ヒーロー検索ボックスのイベント設定
  const heroInput = document.getElementById('drug-search-input');
  if (heroInput) {
    heroInput.addEventListener('input', () => handleHeroSearchInput(heroInput));
    heroInput.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const d = document.getElementById('suggest-dropdown');
        if (d) d.style.display = 'none';
      } else if (e.key === 'Enter') {
        quickSearch(heroInput.value.trim());
      }
    });
  }

  // 小児計算機の初期描画
  calcPediatricDose(10);

  // 腎機能シミュレーターの初期描画
  calcRenalDose();

  // ジアゼパム等価換算計算機の初期化
  initBzdCalculator();

  // 外側クリックでサジェストボックスを閉じる
  document.addEventListener('click', (e) => {
    const sBox = document.getElementById('suggestBox');
    const sInput = document.getElementById('mainSearchInput');
    if (sBox && !sBox.contains(e.target) && e.target !== sInput) {
      sBox.style.display = 'none';
    }

    const dropdown = document.getElementById('suggest-dropdown');
    if (dropdown && !dropdown.contains(e.target) && e.target !== heroInput) {
      dropdown.style.display = 'none';
    }
  });
});


