function filterFirstlineTable() {
  const input = document.getElementById('firstlineFilterInput');
  if (!input) return;
  const terms = input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const rows = document.querySelectorAll('#firstlineTable tbody tr.firstline-row');
  
  rows.forEach(row => {
    if (terms.length === 0) {
      row.style.display = '';
      return;
    }
    const text = row.innerText.toLowerCase();
    const match = terms.every(term => text.includes(term));
    row.style.display = match ? '' : 'none';
  });
}

