let currentMonitorCat = 'all';

function filterMonitorCategory(catClass, btn) {
  currentMonitorCat = catClass;
  const pills = document.querySelectorAll('.monitor-cat-pill');
  pills.forEach(p => {
    p.classList.remove('active');
    p.style.background = '#f8fafc';
    p.style.color = '#334155';
    p.style.borderColor = '#cbd5e1';
  });
  if (btn) {
    btn.classList.add('active');
    btn.style.background = '#6366f1';
    btn.style.color = 'white';
    btn.style.borderColor = '#6366f1';
  }
  filterMonitorTable();
}

function filterMonitorTable() {
  const input = document.getElementById('monitorFilterInput');
  const terms = input ? input.value.trim().toLowerCase().split(/\s+/).filter(Boolean) : [];
  const rows = document.querySelectorAll('#monitorMasterTable tbody tr.monitor-row');
  
  rows.forEach(row => {
    const matchesCat = (currentMonitorCat === 'all') || row.classList.contains(currentMonitorCat);
    if (!matchesCat) {
      row.style.display = 'none';
      return;
    }
    if (terms.length === 0) {
      row.style.display = '';
      return;
    }
    const text = row.innerText.toLowerCase();
    const matchesText = terms.every(t => text.includes(t));
    row.style.display = matchesText ? '' : 'none';
  });
}

