function filterPedsTable() {
  const input = document.getElementById('pedFilterInput');
  const terms = input ? input.value.trim().toLowerCase().split(/\s+/).filter(Boolean) : [];
  const rows = document.querySelectorAll('#pedsMasterTable tbody tr.peds-row');
  
  rows.forEach(row => {
    if (terms.length === 0) {
      row.style.display = '';
      return;
    }
    const text = row.innerText.toLowerCase();
    const match = terms.every(t => text.includes(t));
    row.style.display = match ? '' : 'none';
  });
}

function filterPedsCategory(cat, btn) {
  const btns = document.querySelectorAll('.peds-cat-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const rows = document.querySelectorAll('#pedsMasterTable tbody tr.peds-row');
  rows.forEach(row => {
    if (cat === 'all' || row.getAttribute('data-cat') === cat) {
      row.style.display = '';
    } else {
      row.style.display = 'none';
    }
  });
}

function jumpToPediatric(weight) {
  closeDrugModal();
  switchTab('tab-special');
  showTopic('sec-peds', null);
  const target = document.querySelector('.sec-peds');
  if (target) {
    smoothScrollToElement(target);
    if (weight) {
      const input = document.getElementById('pedWeightInput');
      if (input) {
        input.value = weight;
        calcPediatricDose(weight);
      }
    }
  }
}

