// 複合病態シンドロームの検出関数
function detectComplexSyndrome(rankedDiseases, selectedOptionIds, customDrugs) {
  if (!rankedDiseases || rankedDiseases.length === 0) return null;

  // 上位候補のID一覧
  const topIds = rankedDiseases.slice(0, 3).map(d => d.id);
  const allIds = rankedDiseases.map(d => d.id);

  // マッチするシンドロームを探索
  for (const syn of COMPLEX_SYNDROME_MAP) {
    const matchedComponents = [];
    syn.matchTags.forEach(tag => {
      const found = rankedDiseases.find(d => d.id === tag);
      if (found && !matchedComponents.some(c => c.id === found.id)) {
        matchedComponents.push(found);
      }
    });

    // 2つ以上の構成病態が該当する場合、複合病態として認定！
    if (matchedComponents.length >= 2) {
      return {
        ...syn,
        components: matchedComponents.slice(0, 3)
      };
    }
  }

  return null;
}


// ========================================================
// 医師の処方決定プロセス逆算エンジン（4大深層推論）
// 1. 処方スタンス（攻め Intensive vs 守り Conservative）
// 2. 同種同効薬の分子差別化（Why this drug?）
// 3. 用量フェーズ・警戒度逆算（Dose Titration Stage）
// 4. アドヒアランス・剤形・配合剤設計（Adherence Design）
// ========================================================

// 1. 処方スタンス逆算エンジン
function detectPrescriptionStance(profile, primaryDrug, customDrugs, rankedDiseases) {
  const prof = profile || wizardState.patientProfile || {};
  const isElderly = prof.age === 'elderly' || prof.age === 'senior';
  const isLeanOrFrail = prof.vitals && prof.vitals.has('lean');
  const hasLowEgfr = prof.labs && prof.labs.has('egfr_low');
  const hasBrady = prof.vitals && prof.vitals.has('brady');

  // 守り・QOL守護型（Conservative）の判定
  if ((isElderly && (isLeanOrFrail || hasLowEgfr || hasBrady)) || (isElderly && prof.days === 'as_needed')) {
    return {
      type: 'conservative',
      icon: '🛡️',
      badge: '医師の処方スタンス：守り・QOL守護型（有害事象回避優先）',
      title: '🛡️ 医師の臨床方針：徹底的な数値追求よりも「低血糖・低血圧・転倒骨折」を回避する安全優先の処方設計',
      desc: '患者の年齢（高齢・超高齢）や腎機能・体格（フレイル）を考慮し、ガイドライン目標値に固執せず「自立した日常生活（ADL）の維持」と「医原性有害事象の未然防止」を最優先とした極めて賢明な処方スタンスです。'
    };
  }

  // 攻め・積極的イベント抑制型（Intensive）の判定
  return {
    type: 'intensive',
    icon: '🔥',
    badge: '医師の処方スタンス：攻め・積極的予後改善型（心血管・腎保護優先）',
    title: '🔥 医師の臨床方針：将来の心血管死・脳卒中・透析導入を阻止する「積極的臓器保護」の処方設計',
    desc: '10〜20年後の動脈硬化性イベントや心不全悪化、末期腎不全移行を徹底的に食い止めるため、ガイドライン推奨目標（厳格降圧・脂質低下・心腎保護4本柱）を果敢に追求する攻めの処方スタンスです。'
  };
}

