function detectMoleculeRationale(primaryDrug, customDrugs, selectedOptions) {
  const allTexts = [
    (primaryDrug || ''),
    ...(customDrugs || []),
    (wizardState.rawPrescriptionText || ''),
    ...Array.from(selectedOptions || []).map(id => {
      if (wizardState.activeData) {
        for (const q of wizardState.activeData.questions) {
          const opt = q.options.find(o => o.id === id);
          if (opt) return `${opt.label} ${opt.desc || ''}`;
        }
      }
      return id;
    })
  ].join(' ').toLowerCase();

  const results = [];
  for (const mol of MOLECULE_RATIONALE_MAP) {
    if (mol.pattern.test(allTexts)) {
      results.push(mol);
    }
  }
  return results;
}

// 3. 用量フェーズ・警戒度逆算エンジン
